    private static final String RUN=UUID.randomUUID().toString();private static final ObjectMapper JSON=new ObjectMapper();private static UUID agent,task,batch,secondBatch;
    private static final Map<String,UUID> players=new LinkedHashMap<>(),deliveries=new LinkedHashMap<>(),rejects=new LinkedHashMap<>();private static final Set<String> ready=new HashSet<>(),updated=new HashSet<>(),done=new HashSet<>(),goalDrafts=new HashSet<>();private static int phase,ticks,after;private static boolean failed;
    private static String role(ServerPlayer p){return p.nameAndId().name().equals("DeliveryA")?"A":p.nameAndId().name().equals("DeliveryB")?"B":"";}
    public static boolean enabled(){return Boolean.getBoolean("mineagent.deliverySmokeServer");}
    public static boolean feedbackMode(){return Boolean.getBoolean("mineagent.feedbackSmoke");}
    public static boolean dataMode(){return Boolean.getBoolean("mineagent.feedbackData");}
    private static RuntimeDefinition dataDefinition;private static UUID dataInstance;
