    private static final String DATA_SCRIPT="""
        on('instance.create',function(){
          content.sharedDefine('state','schema',0,JSON.stringify({version:1,fields:{count:{type:'INTEGER',scope:'SHARED',minimum:0,maximum:1},entry:{type:'STRING'},ownerSecret:{type:'STRING',scope:'SHARED',read:'OWNER',write:'OWNER'}}}));
          content.sharedTransact('state','initial',JSON.stringify({schema_version:1,conditions:[],writes:[{key:'count',op:'PUT',value:0},{key:'ownerSecret',op:'PUT',value:'OWNER_FEEDBACK_NOT_VISIBLE'}]}));
          content.placeBlock('marker',0,0,0,'minecraft:stone');
        });
        on('instance.restore',function(){content.placeBlock('marker',0,0,0,'minecraft:stone');content.sharedRead('state');});
        on('feedback.plan',function(e){
          var input=JSON.parse(String(e.payload())),snapshot=JSON.parse(String(e.snapshot()));
          if(snapshot.values.ownerSecret!==undefined)throw new Error('FEEDBACK_OWNER_FIELD_LEAK');
          var denied=false;try{content.state('owner-private');}catch(error){denied=true;}if(!denied)throw new Error('FEEDBACK_PLAN_BORROWED_OWNER_STATE');
          e.plan(JSON.stringify({transaction:{schema_version:1,conditions:[{key:'count',test:'LT',value:1},{key:'entry',test:'ABSENT'}],writes:[{key:'count',op:'ADD',value:1},{key:'entry',op:'PUT_IF_ABSENT',value:input.question}]}}));
        });
        """;
    private static String feedbackPage(){String page=PAGE.replace("<pre id=\"proof\"></pre>","<form id=\"feedback-form\"><label for=\"question\">向该 Agent 记录问题（不调用模型）</label><input id=\"question\"><input type=\"hidden\" id=\"not-sent\" value=\"FEEDBACK_HIDDEN_NOT_SENT\"><button id=\"feedback-submit\">提交反馈</button></form><p id=\"feedback-status\">尚未提交反馈</p><p id=\"feedback-answer\"></p><pre id=\"proof\"></pre>").replace("</html>", """
        <script>let feedbackRecord=null,feedbackOperation=null,feedbackAttempts=0,feedbackError='',feedbackPending=false,feedbackReply='',feedbackShared=null,feedbackBusiness='';addEventListener('mineagent:feedback-data',async e=>{if(e.detail.result?.receipt){try{feedbackBusiness=e.detail.result.receipt.status;feedbackShared=await mineagentFeedback.readShared(e.detail.feedbackId);document.querySelector('#feedback-answer').textContent='事务 '+feedbackBusiness+' · count='+feedbackShared.values.count+' · 我的记录='+(feedbackShared.values.entry||'未写入');}catch(error){feedbackError=error.message;}}});addEventListener('mineagent:feedback-data',e=>{if(e.detail.result?.reply){feedbackReply=e.detail.result.reply;document.querySelector('#feedback-answer').textContent=feedbackReply;}});
        document.querySelector('#feedback-form').addEventListener('submit',async e=>{e.preventDefault();if(feedbackPending)return;feedbackPending=true;feedbackAttempts++;feedbackOperation??=crypto.randomUUID();try{feedbackRecord=await mineagentFeedback.submit('help',{question:document.querySelector('#question').value},feedbackOperation);document.querySelector('#feedback-status').textContent='反馈 '+feedbackRecord.state+' · '+feedbackRecord.feedbackId;}catch(error){feedbackError=error.message;document.querySelector('#feedback-status').textContent=feedbackError;}finally{feedbackPending=false;}});
        window.deliveryProbe=()=>document.querySelector('#proof').textContent='DELIVERY_PROOF:'+JSON.stringify({state,draft:document.querySelector('#draft').value,feedback:feedbackRecord,feedbackOperation,feedbackAttempts,feedbackError,feedbackPending,feedbackReply,feedbackShared,feedbackBusiness});</script></html>
        """);return dataMode()?page.replace("记录问题（不调用模型）","提交共享事务（无模型）"):wakeMode()?page.replace("不调用模型","已授权AI回复"):page;}
