                agent=MineAgentRuntimeServices.bodies(s).createPersistentAt("Delivery test Actor",owner.getUUID(),s.overworld(),owner.position().add(2,0,0)).agentId();task=MineAgentRuntimeServices.tasks(s).create(agent,owner.getUUID(),"Explicit delivery integration fixture",1,List.of(new TaskStepSpec("execute",Set.of()))).taskId();byte[] page=(feedbackMode()?feedbackPage():PAGE).getBytes(StandardCharsets.UTF_8);var files=files(page);var file=files.getFirst();var entries=new LinkedHashMap<String,RuntimeEntrypoint>();entries.put("ui",new RuntimeEntrypoint(file.path(),file.side(),file.sha256()));if(dataMode()){var script=files.stream().filter(f->f.path().equals("server/main.js")).findFirst().orElseThrow();var entry=new RuntimeEntrypoint(script.path(),script.side(),script.sha256());entries.put("server",entry);entries.put("server.restore",entry);}
